{"packet_id": "D027-01", "doc_id": "D027", "jurisdiction": "CA", "category": "screening_restrictions", "lifecycle": "enacted", "title": "California source of income housing discrimination ban", "requirement": "The owner of any housing accommodation may not discriminate against or harass any person because of source of income, which includes public assistance and federal, state or local housing subsidies such as Section 8 vouchers.", "key_value": null, "coverage_conditions": "Any housing accommodation and its owner.", "applicability": {"built_on_or_before": null, "built_after": null, "date_basis": null, "min_units": null, "max_units": null, "owner_dependent": false, "other": "any housing accommodation"}, "exemptions": "Making a written or oral inquiry concerning the level or source of income does not constitute discrimination based on source of income.", "penalty": null, "effective_date": null, "citation": "Cal. Gov. Code § 12955: source of income discrimination", "quoted_span": "(a) For the owner of any housing accommodation to discriminate against or harass any person because of the race, color, religion, sex, gender, gender identity, gender expression, sexual orientation, marital status, national origin, ancestry, familial status, source of income, disability, veteran or military status, or genetic information of that person.", "interaction": null, "confidence": 0.95, "conflict_flag": false, "conflict_note": null}
{"packet_id": "D027-01", "doc_id": "D027", "jurisdiction": "CA", "category": "screening_restrictions", "lifecycle": "enacted", "title": "California income standard, aggregate income of co-tenants", "requirement": "A landlord may not use a financial or income standard in renting housing that fails to account for the aggregate income of persons living together on the same basis as the aggregate income of married persons living together.", "key_value": null, "coverage_conditions": "Any rental of housing in which a financial or income standard is applied.", "applicability": {"built_on_or_before": null, "built_after": null, "date_basis": null, "min_units": null, "max_units": null, "owner_dependent": false, "other": null}, "exemptions": null, "penalty": null, "effective_date": null, "citation": "Cal. Gov. Code § 12955: income standard, aggregate income of unmarried co-tenants", "quoted_span": "(n) To use a financial or income standard in the rental of housing that fails to account for the aggregate income of persons residing together or proposing to reside together on the same basis as the aggregate income\nof married persons residing together or proposing to reside together.", "interaction": null, "confidence": 0.95, "conflict_flag": false, "conflict_note": null}
{"packet_id": "D027-01", "doc_id": "D027", "jurisdiction": "CA", "category": "screening_restrictions", "lifecycle": "enacted", "title": "California credit history alternative evidence with rent subsidy", "requirement": "Where a government rent subsidy is involved, a housing provider using a person’s credit history must offer the applicant the option of providing lawful verifiable alternative evidence of ability to pay the tenant’s portion of rent, and must reasonably consider it in lieu of credit history.", "key_value": null, "coverage_conditions": "Instances in which there is a government rent subsidy; the income standard must be based on the portion of rent to be paid by the tenant.", "applicability": {"built_on_or_before": null, "built_after": null, "date_basis": null, "min_units": null, "max_units": null, "owner_dependent": false, "other": "applies where there is a government rent subsidy"}, "exemptions": "Does not limit the owner’s ability to request information or documentation to verify employment, request landlord references, or verify the identity of a person.", "penalty": null, "effective_date": null, "citation": "Cal. Gov. Code § 12955: credit history, alternative evidence of ability to pay", "quoted_span": "(B) (i) Use a person’s credit history as part of the application process for a rental accommodation without offering the applicant the option, at the applicant’s discretion, of providing lawful, verifiable alternative evidence of the applicant’s reasonable ability to pay\nthe portion of the rent to be paid by the tenant, including, but not limited to, government benefit payments, pay records, and bank statements.", "interaction": null, "confidence": 0.95, "conflict_flag": false, "conflict_note": null}
{"packet_id": "D027-01", "doc_id": "D027", "jurisdiction": "CA", "category": "just_cause_eviction", "lifecycle": "enacted", "title": "California retaliatory eviction prohibited", "requirement": "An owner of housing accommodations may not harass, evict or otherwise discriminate against a person in the sale or rental of housing when the owner’s dominant purpose is retaliation for opposing unlawful practices or participating in a proceeding under this part.", "key_value": null, "coverage_conditions": "Any owner of housing accommodations.", "applicability": {"built_on_or_before": null, "built_after": null, "date_basis": null, "min_units": null, "max_units": null, "owner_dependent": false, "other": null}, "exemptions": null, "penalty": null, "effective_date": null, "citation": "Cal. Gov. Code § 12955: retaliatory eviction prohibited", "quoted_span": "For any owner of housing accommodations to harass, evict, or otherwise discriminate against any person in the sale or rental of housing accommodations when the owner’s dominant purpose is retaliation against a person who has opposed practices unlawful under this section", "interaction": null, "confidence": 0.85, "conflict_flag": false, "conflict_note": null}
